{
  "name": "GSM短信模块",
  "name_en": "GSM SMS Module",
  "manufacturer": "Yoctopuce",
  "description": "用于具备GSM功能的 Yoctopuce 设备的短信收发模块，可管理SIM卡短信存储槽、短信计数器、PDU数据及编码转换，并用于实验室自动化中的远程告警、状态通知和短信交互。",
  "description_en": "An SMS communication module for GSM-enabled Yoctopuce devices. It manages SIM message storage slots, SMS counters, PDU data, and encoding conversion, and is used in lab automation for remote alerts, status notifications, and SMS-based interaction.",
  "tag_hints": [
    "GSM SMS communication",
    "SIM storage management",
    "remote lab alerts",
    "PDU handling",
    "message encoding conversion",
    "Yoctopuce"
  ],
  "actions": [
    {
      "action_name": "auto-set_pduSent",
      "description": "设置外发短信单元计数",
      "description_en": "set the outgoing SMS unit counter"
    },
    {
      "action_name": "auto-set_pduReceived",
      "description": "设置接收短信单元计数",
      "description_en": "set the incoming SMS unit counter"
    },
    {
      "action_name": "auto-set_command",
      "description": "设置命令字符串",
      "description_en": "set the command string"
    },
    {
      "action_name": "auto-nextMsgRef",
      "description": "获取下一条短信的消息引用号",
      "description_en": "get the next SMS message reference"
    },
    {
      "action_name": "auto-clearSIMSlot",
      "description": "清除指定SIM卡短信存储槽",
      "description_en": "clear the specified SIM message storage slot"
    },
    {
      "action_name": "auto-fetchPdu",
      "description": "从指定存储槽读取短信PDU数据",
      "description_en": "fetch SMS PDU data from the specified storage slot"
    },
    {
      "action_name": "auto-initGsm2Unicode",
      "description": "初始化GSM到Unicode的编码转换表",
      "description_en": "initialize the GSM-to-Unicode conversion table"
    },
    {
      "action_name": "auto-gsm2unicode",
      "description": "将GSM编码数据转换为Unicode",
      "description_en": "convert GSM-encoded data to Unicode"
    },
    {
      "action_name": "auto-gsm2str",
      "description": "将GSM编码数据转换为文本字符串",
      "description_en": "convert GSM-encoded data to a text string"
    },
    {
      "action_name": "auto-str2gsm",
      "description": "将文本字符串转换为GSM编码",
      "description_en": "convert a text string to GSM encoding"
    },
    {
      "action_name": "auto-checkNewMessages",
      "description": "检查并整理新收到的短信",
      "description_en": "check for and assemble newly received SMS messages"
    },
    {
      "action_name": "auto-clearPduCounters",
      "description": "清除短信收发计数器",
      "description_en": "clear the SMS send/receive counters"
    },
    {
      "action_name": "auto-sendTextMessage",
      "description": "发送普通文本短信",
      "description_en": "send a regular text SMS message"
    },
    {
      "action_name": "auto-sendFlashMessage",
      "description": "发送闪信短信",
      "description_en": "send a flash SMS message"
    },
    {
      "action_name": "auto-newMessage",
      "description": "创建一条待配置和发送的新短信",
      "description_en": "create a new SMS message for later configuration and sending"
    },
    {
      "action_name": "auto-nextMessageBox",
      "description": "枚举下一个可访问的短信消息接口",
      "description_en": "enumerate the next accessible SMS message box interface"
    }
  ]
}

